-- ===========================================================================
-- 0040_content_coverage.sql
--
-- K-12 Reading, Writing and Math coverage, counted live for /admin/coverage,
-- the way 0034 does it for SAT. Platform admins only.
--
-- HOW TO APPLY: paste into the Supabase SQL editor for papiowjjoyhnbyhgtbxq and
-- run once. Idempotent. Then run 0040_content_coverage_verify.sql. Deploy the
-- page only after both.
--
-- ---------------------------------------------------------------------------
-- WHAT CHANGES
-- ---------------------------------------------------------------------------
--  coverage_targets     Every skill the standards call for, K to 12, in Reading,
--                       Writing and Math (455 rows, from
--                       docs/coverage/k12-coverage-report.md): subject, grade,
--                       group, name, the Common Core codes, and the skill slug(s)
--                       that cover it, live or planned (read-g8-theme-summary).
--                       No browser access.
--  question_issues(q)   The automated checks for any question: four choices,
--                       one correct, a named mistake on every wrong choice, the
--                       stored answer matches the correct choice, an
--                       explanation, all choices different, no dashes, and a
--                       stem ending in a question mark or colon.
--  content_coverage()   Per target: whether a skill exists, and its drafted,
--                       checks passing, reviewed, published and published and
--                       reviewed counts, against a target of 40. Platform
--                       admins only.
--
-- ---------------------------------------------------------------------------
-- ROLLBACK (by hand)
-- ---------------------------------------------------------------------------
--  begin;
--  drop function if exists public.content_coverage();
--  drop function if exists public.question_issues(public.generated_questions);
--  drop table if exists public.coverage_targets;
--  commit;
-- ===========================================================================

begin;

-- ---------------------------------------------------------------------------
-- 1) The targets.
-- ---------------------------------------------------------------------------
create table if not exists public.coverage_targets (
  subject     text not null check (subject in ('reading', 'writing', 'math')),
  grade       integer not null check (grade between 0 and 12),
  grp         text not null,
  name        text not null,
  standards   text[] not null,
  skill_slugs text[] not null check (cardinality(skill_slugs) >= 1),
  sort        integer not null,
  target      integer not null default 40 check (target > 0),
  primary key (subject, grade, name)
);
alter table public.coverage_targets enable row level security;
revoke all on public.coverage_targets from public, anon, authenticated;

on conflict (subject, grade, name) do update set
  grp = excluded.grp, standards = excluded.standards, skill_slugs = excluded.skill_slugs, sort = excluded.sort;

-- ---------------------------------------------------------------------------
-- 2) The automated checks, for any question.
-- ---------------------------------------------------------------------------
create or replace function public.question_issues(q public.generated_questions)
returns text[]
language sql
stable
security definer
set search_path = ''
as $$
  with c as (
    select e.value as v, e.ordinality as i
      from jsonb_array_elements(case when jsonb_typeof(q.choices) = 'array' then q.choices else '[]'::jsonb end)
           with ordinality as e(value, ordinality)
  ),
  facts as (
    select
      (select count(*) from c) as n,
      (select count(*) from c where (c.v ->> 'is_correct') = 'true') as n_correct,
      (select count(*) from c where (c.v ->> 'is_correct') is distinct from 'true'
                                 and coalesce(btrim(c.v ->> 'misconception_token'), '') = '') as n_wrong_untagged,
      (select c.v ->> 'text' from c where (c.v ->> 'is_correct') = 'true' order by c.i limit 1) as correct_text,
      (select count(distinct lower(btrim(c.v ->> 'text'))) from c) as n_distinct,
      (select string_agg(coalesce(c.v ->> 'text', ''), ' ') from c) as all_text
  )
  select array_remove(array[
    case when f.n <> 4 then 'four_choices' end,
    case when f.n_correct <> 1 then 'one_correct' end,
    case when f.n_wrong_untagged > 0 then 'distractor_misconceptions' end,
    case when f.correct_text is distinct from q.correct_answer then 'answer_matches_choice' end,
    case when coalesce(btrim(q.solution), '') = '' then 'has_solution' end,
    case when f.n_distinct <> f.n then 'distinct_choices' end,
    case when concat_ws(' ', q.stem, f.all_text, q.solution, q.correct_answer) ~ '[—–]|\s-\s|--' then 'no_dashes' end,
    case when btrim(coalesce(q.stem, '')) !~ '[?:]$' then 'stem_ends' end
  ], null)
  from facts f;
$$;

-- ---------------------------------------------------------------------------
-- 3) Live counts per target. Platform admins only.
-- ---------------------------------------------------------------------------
create or replace function public.content_coverage()
returns table (
  subject text, grade integer, grp text, name text, standards text[], skill_slugs text[], sort integer, target integer,
  skill_exists boolean, drafted integer, checks_passing integer, reviewed integer, published integer,
  published_reviewed integer
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_platform_admin() then
    raise exception 'platform_admin_required' using errcode = 'insufficient_privilege';
  end if;
  return query
    select t.subject, t.grade, t.grp, t.name, t.standards, t.skill_slugs, t.sort, t.target,
           exists (select 1 from public.skills k where k.slug = any (t.skill_slugs)),
           count(q.id) filter (where q.status <> 'retired')::integer,
           count(q.id) filter (where q.status <> 'retired' and cardinality(public.question_issues(q)) = 0)::integer,
           count(q.id) filter (where q.status <> 'retired' and q.reviewed_at is not null)::integer,
           count(q.id) filter (where q.status = 'published')::integer,
           count(q.id) filter (where q.status = 'published' and q.reviewed_at is not null)::integer
      from public.coverage_targets t
      left join public.skills k on k.slug = any (t.skill_slugs)
      left join public.generated_questions q on q.skill_id = k.id
     group by t.subject, t.grade, t.grp, t.name, t.standards, t.skill_slugs, t.sort, t.target
     order by t.sort;
end;
$$;

-- ---------------------------------------------------------------------------
-- 4) Grants (CLAUDE.md: revoke from public and anon, grant explicitly).
-- ---------------------------------------------------------------------------
revoke all on function public.question_issues(public.generated_questions) from public, anon, authenticated;
revoke all on function public.content_coverage() from public, anon;
grant execute on function public.question_issues(public.generated_questions) to service_role;
grant execute on function public.content_coverage() to authenticated, service_role;

commit;
